#### REQ-LENS-004-005: Java SDK Usage Guidelines

**Status**: Recommended (Phase 2)
**Rationale**: Standardize Java-based integration

**Java SDK Dependency**:
```xml
<dependency>
    <groupId>io.lenses</groupId>
    <artifactId>lenses-java-client</artifactId>
    <version>5.0.0</version>
</dependency>
```

**Common Operations**:
```java
// Placeholder: Java SDK examples
import io.lenses.LensesClient;
import io.lenses.models.Topic;
import io.lenses.models.ConsumerGroup;

public class LensesExample {
    public static void main(String[] args) {
        // Initialize client
        LensesClient client = LensesClient.builder()
            .url("https://lenses.prod.company.com")
            .token(System.getenv("LENSES_API_TOKEN"))
            .build();

        // List topics
        List<Topic> topics = client.topics().list();
        topics.forEach(topic ->
            System.out.println("Topic: " + topic.getName() +
                             ", Partitions: " + topic.getPartitions())
        );

        // Query consumer lag
        ConsumerGroup consumerGroup = client.consumerGroups()
            .get("medicaid-claims-processor-prod");
        System.out.println("Consumer lag: " + consumerGroup.getTotalLagMinutes());

        // Execute SQL query
        List<Map<String, Object>> results = client.sql()
            .execute("SELECT * FROM medicaid.claims.submitted.v1 LIMIT 100");
        results.forEach(System.out::println);
    }
}
